    typeof(VaultGame).GetMethod("DropChampionReward",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(game,new object[]{rewardFoe,true});
    File.WriteAllText(Output+"/champion-check.txt","Elite reward and boss reward factories invoked successfully; elite HP="+rewardFoe.maxHp+" bar="+rewardFoe.HealthBarColor);
    File.WriteAllText(Output+"/result.txt","UI and encounter capture complete. SpawnRecords="+game.OverworldEnemySpawnCount);yield break;
