    game.enabled=false;var buildings=game.WorldGeography.GetChunk(12,15).Buildings;if(buildings.Count>0){var b=buildings[0];var player=(Transform)typeof(VaultGame).GetField("player",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(game);player.position=new Vector3(b.xMax+1,.65f,b.yMax+1);typeof(VaultGame).GetMethod("UpdateCamera",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(game,new object[]{true});}
