   game.invincible=99999;game.CompleteWorldBossConversation();game.BuildHub();yield return null;yield return Capture(game,"hub");VerifyCovers();
   game.enabled=false;var oldCam=game.GameCamera.transform.position;float oldSize=game.GameCamera.orthographicSize;game.GameCamera.orthographicSize=2.2f;var boss=FindAnyObjectByType<ImportedEnemyVisual>();var npc=ImportedEnemyVisual.TryCreateBossNPC(null,new Vector3(0,0,0));npc.rotation=Quaternion.Euler(0,180,0);var bounds=new Bounds(npc.position,Vector3.one);bool first=true;foreach(var r in npc.GetComponentsInChildren<Renderer>()){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}game.GameCamera.transform.position=bounds.center-game.GameCamera.transform.forward*12;yield return Capture(game,"boss-close");Destroy(npc.gameObject);game.GameCamera.transform.position=oldCam;game.GameCamera.orthographicSize=oldSize;game.enabled=true;
