  IEnumerator Capture(VaultGame game,string name,float speed=-1,bool attack=false){yield return null;if(speed>=0){var visual=game.Enemies[game.Enemies.Count-1].GetComponentInChildren<ImportedEnemyVisual>();if(attack)typeof(ImportedEnemyVisual).GetField("attackTime",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(visual,.25f);typeof(ImportedEnemyVisual).GetMethod("Animate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(visual,new object[]{.25f,speed});}var cam=game.GameCamera;var rt=new RenderTexture(1280,900,24);var old=cam.targetTexture;var active=RenderTexture.active;var texture=new Texture2D(1280,900,TextureFormat.RGB24,false);cam.targetTexture=rt;foreach(var batch in FindObjectsByType<ImportedWorldBatch>(FindObjectsSortMode.None))batch.DrawNow();cam.Render();RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,1280,900),0,0);texture.Apply();File.WriteAllBytes(Output+"/"+name+".png",texture.EncodeToPNG());cam.targetTexture=old;RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(texture);}
